#pragma once
#include <functional>
#include <memory>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <set>
#include <mutex>
#include <algorithm>
#include <atomic>

namespace mkt {

// Observer/Observable pair with proper lifetime management
class Observable;
class Observer {
public:
    virtual ~Observer() = default;
    virtual void update() = 0;
protected:
    void observe(const std::shared_ptr<Observable>& o);
    void stop_observing(const std::shared_ptr<Observable>& o);
};

class Observable {
public:
    virtual ~Observable() = default;
    void notify();

    // For internal use by Observer
    void add_observer(const std::shared_ptr<Observer>& o);
    void remove_observer(const std::shared_ptr<Observer>& o);

private:
    std::unordered_set<std::weak_ptr<Observer>> observers_;
    mutable std::mutex mutex_;
};

// A mutable market value. set() with the current value does nothing.
class Quote : public Observable {
public:
    explicit Quote(double v);
    double value() const;
    void set(double v);

private:
    double value_;
    mutable std::mutex mutex_;
};

// Lazily computed value. value() recomputes only if a dependency changed since the last
// computation; a LazyObject that was invalidated forwards the notification once to its
// own observers, and does not forward again until it has been recomputed.
class LazyObject : public Observer, public Observable {
public:
    double value() const;
    long computations() const;   // how many times compute() ran
    void update() override;

protected:
    virtual double compute() const = 0;

private:
    mutable std::atomic<bool> dirty_{true};
    mutable std::atomic<double> cached_value_{0.0};
    mutable std::atomic<long> computations_{0};
    mutable std::mutex mutex_;
    mutable std::unordered_set<std::weak_ptr<Observable>> dependencies_;
    mutable std::mutex dependencies_mutex_;

    // For dependency tracking
    void add_dependency(const std::shared_ptr<Observable>& o);
    void remove_dependency(const std::shared_ptr<Observable>& o);
};

// Black-Scholes forward-free price model used by tests.
struct Engine {
    virtual ~Engine() = default;
    virtual double price(double spot, double strike, double vol) const = 0;
    virtual std::string name() const = 0;
};

// Name -> maker registry. REGISTER_ENGINE(key, Class), used at namespace scope in any
// translation unit, makes create(key) return a new Class. Built in: "intrinsic" prices
// max(spot - strike, 0) + vol, and "flat" prices strike.
class EngineFactory {
public:
    static EngineFactory& instance();
    void add(const std::string& key, std::function<std::unique_ptr<Engine>()> maker);
    std::unique_ptr<Engine> create(const std::string& key) const;   // std::invalid_argument if unknown
    std::vector<std::string> keys() const;                          // sorted

private:
    std::unordered_map<std::string, std::function<std::unique_ptr<Engine>()>> makers_;
    mutable std::mutex mutex_;
};

// Helper macro for registration
#define REGISTER_ENGINE(key, Class) \
    static struct Register##Class { \
        Register##Class() { \
            mkt::EngineFactory::instance().add(key, []() { return std::make_unique<Class>(); }); \
        } \
    } register_##Class##_##key;

// Decorator: same interface as the wrapped engine, caches price() by exact argument
// triple. clear() empties the cache. name() is "memo(" + wrapped name + ")".
class MemoEngine : public Engine {
public:
    explicit MemoEngine(std::unique_ptr<Engine> inner);
    double price(double spot, double strike, double vol) const override;
    std::string name() const override;
    void clear();

private:
    std::unique_ptr<Engine> inner_;
    mutable std::unordered_map<std::tuple<double, double, double>, double> cache_;
    mutable std::mutex mutex_;
};

}  // namespace mkt

